const PAYLOAD = [{"id":"personnages-verite-chasseurs-stephen-fushen","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Stephen Fushen","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs shientaoïstes","Humaine"],"pnj":{"real_name":"Stephen FUSHEN","nom_verite":"","race":"Humaine","age":"« 75 ans »","origine":"américaine","statut":"chasseurs religieux","statut_verite":"Pépé king fu","relations":[],"source_group":"Chasseurs shientaoïstes","source_order":40,"identity_keys":["stephen fushen"],"source_verite":[{"label":"Informations Vérité","text":"Stephen est né dans les années 1960 à New-York. Son père était chinois mais sa mère était elle￾même née à New-York. Très jeune, il était assez violent, utilisant les quelques bases de Wushu que lui enseigna son père pour tyranniser ceux qu’il n’aimait pas. Il attaquait essentiellement ceux qu’il sentait différents, dit comme cela, il apparaissait purement raciste, mais en vérité, il sentait probablement déjà les essences inhumaines. Il est tombé dans le confucianisme après une jeunesse agitée pendant laquelle il fut soupçonné de meurtre bien que blanchi depuis. En vérité, l’avocat qu’on lui paya était un chasseur confucéen, sentant un grand talent dans le jeune, il lui enseigna tout ce qu’il pouvait. Kevin restait un bagarreur, mais appris à se contrôler et devint au fil des années, de plus en plus sage, réussissant dans des études de commerces, il devint un trader puis un économiste réputé, se forgeant une sacrée fortune en quelques décennies. Il ne lâcha pas les arts-martiaux pour autant, créant plusieurs associations d’art-martiaux chinois et lançant plusieurs compétitions. Agé de 62 ans lorsque la guerre éclata, il ne fut pas accepté avec les premiers volontaires, étant trop vieux, mais on ne regarda pas son âge lors du second engagement, quand il fallut reconstituer l’armée à la hâte. Il usa de sa fortune pour rapidement devenir colonel, il est à l’origine de plusieurs massacres de la population coréenne, nord comme sud, orientant les bombardements sur des nids de créatures. Sur la toute fin de la guerre, il quitta l’armée, mais il engagea presque toute sa fortune dans les équipes de recherche de Leslie Wright, notamment en finançant plus personnellement le professeur Karamov. Après la guerre, il fut un des premiers civils à supporter des opérations d’augmentations, ayant engagé le peu d’argent qui lui restait dans de jeunes entreprises, il vécut assez pauvrement jusqu’à l’essor des Megacorporation, son compte en banque gonflant alors proportionnellement à leurs gains, redevenant riche assez vite."}],"source_extract":"Stephen Fushen\nPépé king fu\nNom de la Réalité : Stephen FUSHEN\nNom de la Vérité : _\nAge : « 75 ans »\nAffiliations :\nchasseurs religieux\nNationalité d’origine : américaine\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nStephen est né dans les années 1960 à New-York. Son père était chinois mais sa mère était elle￾même née à New-York.\nTrès jeune, il était assez violent, utilisant les quelques bases de Wushu que lui enseigna son père\npour tyranniser ceux qu’il n’aimait pas. Il attaquait essentiellement ceux qu’il sentait différents, dit\ncomme cela, il apparaissait purement raciste, mais en vérité, il sentait probablement déjà les\nessences inhumaines.\nIl est tombé dans le confucianisme après une jeunesse agitée pendant laquelle il fut soupçonné de\nmeurtre bien que blanchi depuis.\nEn vérité, l’avocat qu’on lui paya était un chasseur confucéen, sentant un grand talent dans le jeune,\nil lui enseigna tout ce qu’il pouvait.\nKevin restait un bagarreur, mais appris à se contrôler et devint au fil des années, de plus en plus sage,\nréussissant dans des études de commerces, il devint un trader puis un économiste réputé, se\nforgeant une sacrée fortune en quelques décennies.\nIl ne lâcha pas les arts-martiaux pour autant, créant plusieurs associations d’art-martiaux chinois et\nlançant plusieurs compétitions.\nAgé de 62 ans lorsque la guerre éclata, il ne fut pas accepté avec les premiers volontaires, étant trop\nvieux, mais on ne regarda pas son âge lors du second engagement, quand il fallut reconstituer\nl’armée à la hâte. Il usa de sa fortune pour rapidement devenir colonel, il est à l’origine de plusieurs\nmassacres de la population coréenne, nord comme sud, orientant les bombardements sur des nids\nde créatures.\nSur la toute fin de la guerre, il quitta l’armée, mais il engagea presque toute sa fortune dans les\néquipes de recherche de Leslie Wright, notamment en finançant plus personnellement le professeur\nKaramov.\nAprès la guerre, il fut un des premiers civils à supporter des opérations d’augmentations, ayant\nengagé le peu d’argent qui lui restait dans de jeunes entreprises, il vécut assez pauvrement jusqu’à\nl’essor des Megacorporation, son compte en banque gonflant alors proportionnellement à leurs\ngains, redevenant riche assez vite.","source_heading":"Stephen Fushen"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Stephen FUSHEN"],["Nom de la Vérité","_"],["Âge","« 75 ans »"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","américaine"],["Nature réelle","Humaine"],["Repère","Pépé king fu"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Stephen est né dans les années 1960 à New-York. Son père était chinois mais sa mère était elle￾même née à New-York. Très jeune, il était assez violent, utilisant les quelques bases de Wushu que lui enseigna son père pour tyranniser ceux qu’il n’aimait pas. Il attaquait essentiellement ceux qu’il sentait différents, dit comme cela, il apparaissait purement raciste, mais en vérité, il sentait probablement déjà les essences inhumaines. Il est tombé dans le confucianisme après une jeunesse agitée pendant laquelle il fut soupçonné de meurtre bien que blanchi depuis. En vérité, l’avocat qu’on lui paya était un chasseur confucéen, sentant un grand talent dans le jeune, il lui enseigna tout ce qu’il pouvait. Kevin restait un bagarreur, mais appris à se contrôler et devint au fil des années, de plus en plus sage, réussissant dans des études de commerces, il devint un trader puis un économiste réputé, se forgeant une sacrée fortune en quelques décennies. Il ne lâcha pas les arts-martiaux pour autant, créant plusieurs associations d’art-martiaux chinois et lançant plusieurs compétitions. Agé de 62 ans lorsque la guerre éclata, il ne fut pas accepté avec les premiers volontaires, étant trop vieux, mais on ne regarda pas son âge lors du second engagement, quand il fallut reconstituer l’armée à la hâte. Il usa de sa fortune pour rapidement devenir colonel, il est à l’origine de plusieurs massacres de la population coréenne, nord comme sud, orientant les bombardements sur des nids de créatures. Sur la toute fin de la guerre, il quitta l’armée, mais il engagea presque toute sa fortune dans les équipes de recherche de Leslie Wright, notamment en finançant plus personnellement le professeur Karamov. Après la guerre, il fut un des premiers civils à supporter des opérations d’augmentations, ayant engagé le peu d’argent qui lui restait dans de jeunes entreprises, il vécut assez pauvrement jusqu’à l’essor des Megacorporation, son compte en banque gonflant alors proportionnellement à leurs gains, redevenant riche assez vite."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-valle-von-hardenberg","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Valle Von Hardenberg","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs kabbalistes","humaine"],"pnj":{"real_name":"Valle Von HARDENBERG","nom_verite":"","race":"humaine","age":"«52 ans » - 92 ans","origine":"Allemand","statut":"chasseurs religieux","statut_verite":"L’apôtre de la Kabbale","relations":[],"source_group":"Chasseurs kabbalistes","source_order":41,"identity_keys":["valle von hardenberg"],"source_verite":[],"source_extract":"Valle Von Hardenberg\nL’apôtre de la Kabbale\nNom de la Réalité : Valle Von HARDENBERG\nNom de la Vérité : _\nAge : «52 ans » - 92 ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Allemand\nEthnie réelle : humaine\nPersonnages liés :\n ?\n___________________________________________________________________________\nInformations Réalité :\nValle est un kabbaliste né en Allemagne en 1943\nC’est le frère jumeau de Aaron von HARDENBERG, le maitre de la Loge des Mages de Berlin.\nIls sont nés tous les deux dans l’illustre famille des Hardenberg, des mages de lignée assez ancienne.\nÊtre Mage de lignée n’est pas souvent compatible avec la religion, cependant, quand leur père,\nMaximilian von HARDENBERG, décida de procréer, il jeta son dévolu sur des trains de juifs déportés\nqu’il détourna. Non pas par humanisme, mais par pur profit, il récupéra des wagons et sélectionna la\nfemme au Mageius le plus puissant, il se fichait qu’elle n’ait que 17 ans et soit assez laide, il offrit aux\nautres l’opportunité de le servir et libéra ceux qui refusèrent, pour mieux les dénoncer derrière. Les\njumeaux naquirent donc dans la foi hébraïque à une époque difficile. Leur père fut assez mécontent\nd’avoir des jumeaux, il s’avait que pour les monozygotes, il n’y avait pas deux Mageius possible, un\nenfant serait possiblement Mage mais jamais l’autre.\nValle fut celui sans pouvoir, aux débuts, sa mère le surprotégea en comprenant que son père n’avait\naucun intérêt pour ce futur serviteur d’Aaron, le frère, elle lui donna l’espoir par la foi juive,\ntoutefois, au fur et à mesure qu’il grandissait, sa mère tout comme son frère, progressaient dans\nl’apprentissage de la Magie, toutes les croyances de sa mère furent remises en question alors qu’elle\ndécouvrait son véritable potentiel, abandonnant sa foi pour se consacrer à la magie corps et âme.\nValle n’eut pas ce choix, en 1964, à 21 ans, il se rendit en Israël, se sentant souillé d’être un sorcier et\ncherchant sa rédemption, échappant à son père grâce à son frère, qui, malgré tout ce qui les\nséparait, restait la personne le comprenant le mieux. Valle y découvrit la Kabbale véritable en étant\ntraqué par des chasseurs, c’est prisonnier d’une confrérie kabbaliste qu’il préféra trahir les Mages et\nles sorciers en échange d’être accepté par la société secrète. Le prix pour qu’on l’initie était les vies\nde son père et de sa mère, qu’on assassina quelques semaines plus tard.\nValle progressa lentement, on se méfiait de l’ancien sorcier, à côté, Aaron, son jumeau lui vendit bien\ndes Mages, offrant à Valle une valeur réelle pendant qu’Aaron nettoyait un chemin jusque-là\ninaccessible à la tête de la loge de Berlin.\nLes deux jumeaux restent alliés malgré leurs factions parfois opposées, désormais, Valle, maintenu\nen vie par son frère, est à la tête de la confrérie Kabbaliste la plus puissante d’Israël.","source_heading":"Valle Von Hardenberg"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Valle Von HARDENBERG"],["Nom de la Vérité","_"],["Âge","«52 ans » - 92 ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Allemand"],["Nature réelle","humaine"],["Repère","L’apôtre de la Kabbale"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"Valle est un kabbaliste né en Allemagne en 1943 C’est le frère jumeau de Aaron von HARDENBERG, le maitre de la Loge des Mages de Berlin. Ils sont nés tous les deux dans l’illustre famille des Hardenberg, des mages de lignée assez ancienne. Être Mage de lignée n’est pas souvent compatible avec la religion, cependant, quand leur père, Maximilian von HARDENBERG, décida de procréer, il jeta son dévolu sur des trains de juifs déportés qu’il détourna. Non pas par humanisme, mais par pur profit, il récupéra des wagons et sélectionna la femme au Mageius le plus puissant, il se fichait qu’elle n’ait que 17 ans et soit assez laide, il offrit aux autres l’opportunité de le servir et libéra ceux qui refusèrent, pour mieux les dénoncer derrière. Les jumeaux naquirent donc dans la foi hébraïque à une époque difficile. Leur père fut assez mécontent d’avoir des jumeaux, il s’avait que pour les monozygotes, il n’y avait pas deux Mageius possible, un enfant serait possiblement Mage mais jamais l’autre. Valle fut celui sans pouvoir, aux débuts, sa mère le surprotégea en comprenant que son père n’avait aucun intérêt pour ce futur serviteur d’Aaron, le frère, elle lui donna l’espoir par la foi juive, toutefois, au fur et à mesure qu’il grandissait, sa mère tout comme son frère, progressaient dans l’apprentissage de la Magie, toutes les croyances de sa mère furent remises en question alors qu’elle découvrait son véritable potentiel, abandonnant sa foi pour se consacrer à la magie corps et âme. Valle n’eut pas ce choix, en 1964, à 21 ans, il se rendit en Israël, se sentant souillé d’être un sorcier et cherchant sa rédemption, échappant à son père grâce à son frère, qui, malgré tout ce qui les séparait, restait la personne le comprenant le mieux. Valle y découvrit la Kabbale véritable en étant traqué par des chasseurs, c’est prisonnier d’une confrérie kabbaliste qu’il préféra trahir les Mages et les sorciers en échange d’être accepté par la société secrète. Le prix pour qu’on l’initie était les vies de son père et de sa mère, qu’on assassina quelques semaines plus tard. Valle progressa lentement, on se méfiait de l’ancien sorcier, à côté, Aaron, son jumeau lui vendit bien des Mages, offrant à Valle une valeur réelle pendant qu’Aaron nettoyait un chemin jusque-là inaccessible à la tête de la loge de Berlin. Les deux jumeaux restent alliés malgré leurs factions parfois opposées, désormais, Valle, maintenu en vie par son frère, est à la tête de la confrérie Kabbaliste la plus puissante d’Israël."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-levanah-uriel","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Levanah Uriel","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs kabbalistes","Sephirienne"],"pnj":{"real_name":"Levanah URIEL","nom_verite":"","race":"Sephirienne","age":"«47 ans » - ???","origine":"Israélienne","statut":"chasseurs religieux","statut_verite":"Dernière Sephirienne","relations":["Catalina de la CAZA","Leslie WRIGHT","Saskia"],"source_group":"Chasseurs kabbalistes","source_order":42,"identity_keys":["levanah uriel"],"source_verite":[{"label":"Informations Vérité","text":"Levanah est une des filles de Levey URIEL, l’actuel grand rabbin californien, ancien directeur du Mossad et plus grand chasseur Kabbaliste d’Israël. Son père engrossa une sorcière afin de s’assurer que la fille serait dotée des mêmes dons. Dès ses 10 ans, elle fut entrainée afin de remplir trois missions :  Trouver Baldwin VANDRICK et exterminer sa lignée de chasseurs renégats.  Trouver l’engeance de Ux'sharith Bellatheis et la tuer avant qu’elle n’éveille ses pouvoirs.  Organiser la purge des sorcières psycolors, des pauvres âmes corrompues par un fléau. Agée de 15 ans, elle fut envoyée en Suisse pour être intégrée à l’Académie des Saintes Lagunes, au plus près de Vandrick et sa famille. Elle étudia jusqu’à ses 22 ans pour un doctorat en médecine puis elle obtint à 26 ans un doctorat en génétique afin de mettre au point un virus exterminant les sorcières psycolors. En 2014, à 26 ans, elle intégra l’ordre des saintes lagunes sur recommandation d’un amant manipulé, rencontrant Amily VANDRICK et Catalina de la CAZA avec qui elle sympathisa bien qu’elle devait les tuer toutes les deux. En 2020, elle se fit arracher sa part de sorcière par Alisa SVALISDOTTIR lors du grand tournoi des sorcières psycolors. Contrairement à Catalina, cela fit pratiquement mourir Levanah qu’on rapatria d’urgence en Israël. Levey fit forcer l’ouverture de son arbre de vie pour la faire régénérer et perdre assez d’Humanité afin que le vide créé dans son âme ne soit compensé. Pendant deux ans, elle traqua des démons pour « crucifier » ces derniers à ses Sephiroth et compléter son arbre de vie, devenant la dernière Sephirienne à apparaitre depuis des siècles. Elle intégra le PCRC par ses grandes connaissances et ses nouveaux dons intellectuels récemment acquis, aidant beaucoup Leslie WRIGHT pour ce qui était de la partie biologie. Elle créa ensuite Biosun, la megacorporation écrasante en biomédical. En tant que Sephirienne, elle est détestée des Angelus comme des Daemons"}],"source_extract":"Levanah Uriel\nDernière Sephirienne\nNom de la Réalité : Levanah URIEL\nNom de la Vérité : _\nAge : «47 ans » - ???\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Israélienne\nEthnie réelle : Sephirienne\nPersonnages liés :\n Catalina de la CAZA\n Leslie WRIGHT\n Saskia\n___________________________________________________________________________\nInformations vérité :\nLevanah est une des filles de Levey URIEL, l’actuel grand rabbin californien, ancien directeur du\nMossad et plus grand chasseur Kabbaliste d’Israël.\nSon père engrossa une sorcière afin de s’assurer que la fille serait dotée des mêmes dons.\nDès ses 10 ans, elle fut entrainée afin de remplir trois missions :\n Trouver Baldwin VANDRICK et exterminer sa lignée de chasseurs renégats.\n Trouver l’engeance de Ux'sharith Bellatheis et la tuer avant qu’elle n’éveille ses pouvoirs.\n Organiser la purge des sorcières psycolors, des pauvres âmes corrompues par un fléau.\nAgée de 15 ans, elle fut envoyée en Suisse pour être intégrée à l’Académie des Saintes Lagunes, au\nplus près de Vandrick et sa famille. Elle étudia jusqu’à ses 22 ans pour un doctorat en médecine puis\nelle obtint à 26 ans un doctorat en génétique afin de mettre au point un virus exterminant les\nsorcières psycolors.\nEn 2014, à 26 ans, elle intégra l’ordre des saintes lagunes sur recommandation d’un amant manipulé,\nrencontrant Amily VANDRICK et Catalina de la CAZA avec qui elle sympathisa bien qu’elle devait les\ntuer toutes les deux.\nEn 2020, elle se fit arracher sa part de sorcière par Alisa SVALISDOTTIR lors du grand tournoi des\nsorcières psycolors. Contrairement à Catalina, cela fit pratiquement mourir Levanah qu’on rapatria\nd’urgence en Israël. Levey fit forcer l’ouverture de son arbre de vie pour la faire régénérer et perdre\nassez d’Humanité afin que le vide créé dans son âme ne soit compensé.\nPendant deux ans, elle traqua des démons pour « crucifier » ces derniers à ses Sephiroth et\ncompléter son arbre de vie, devenant la dernière Sephirienne à apparaitre depuis des siècles.\nElle intégra le PCRC par ses grandes connaissances et ses nouveaux dons intellectuels récemment\nacquis, aidant beaucoup Leslie WRIGHT pour ce qui était de la partie biologie. Elle créa ensuite\nBiosun, la megacorporation écrasante en biomédical.\nEn tant que Sephirienne, elle est détestée des Angelus comme des Daemons","source_heading":"Levanah Uriel"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Levanah URIEL"],["Nom de la Vérité","_"],["Âge","«47 ans » - ???"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Israélienne"],["Nature réelle","Sephirienne"],["Personnages liés","Catalina de la CAZA · Leslie WRIGHT · Saskia"],["Repère","Dernière Sephirienne"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Levanah est une des filles de Levey URIEL, l’actuel grand rabbin californien, ancien directeur du Mossad et plus grand chasseur Kabbaliste d’Israël. Son père engrossa une sorcière afin de s’assurer que la fille serait dotée des mêmes dons. Dès ses 10 ans, elle fut entrainée afin de remplir trois missions :  Trouver Baldwin VANDRICK et exterminer sa lignée de chasseurs renégats.  Trouver l’engeance de Ux'sharith Bellatheis et la tuer avant qu’elle n’éveille ses pouvoirs.  Organiser la purge des sorcières psycolors, des pauvres âmes corrompues par un fléau. Agée de 15 ans, elle fut envoyée en Suisse pour être intégrée à l’Académie des Saintes Lagunes, au plus près de Vandrick et sa famille. Elle étudia jusqu’à ses 22 ans pour un doctorat en médecine puis elle obtint à 26 ans un doctorat en génétique afin de mettre au point un virus exterminant les sorcières psycolors. En 2014, à 26 ans, elle intégra l’ordre des saintes lagunes sur recommandation d’un amant manipulé, rencontrant Amily VANDRICK et Catalina de la CAZA avec qui elle sympathisa bien qu’elle devait les tuer toutes les deux. En 2020, elle se fit arracher sa part de sorcière par Alisa SVALISDOTTIR lors du grand tournoi des sorcières psycolors. Contrairement à Catalina, cela fit pratiquement mourir Levanah qu’on rapatria d’urgence en Israël. Levey fit forcer l’ouverture de son arbre de vie pour la faire régénérer et perdre assez d’Humanité afin que le vide créé dans son âme ne soit compensé. Pendant deux ans, elle traqua des démons pour « crucifier » ces derniers à ses Sephiroth et compléter son arbre de vie, devenant la dernière Sephirienne à apparaitre depuis des siècles. Elle intégra le PCRC par ses grandes connaissances et ses nouveaux dons intellectuels récemment acquis, aidant beaucoup Leslie WRIGHT pour ce qui était de la partie biologie. Elle créa ensuite Biosun, la megacorporation écrasante en biomédical. En tant que Sephirienne, elle est détestée des Angelus comme des Daemons"}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-jude-riot","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Jude Riot","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs kabbalistes","Nephilim"],"pnj":{"real_name":"Jude RIOT","nom_verite":"Juda ISCARIOT/ Judhaniel","race":"Nephilim","age":"« 25 ans - « ???» ans","origine":"Américaine","statut":"chasseurs religieux","statut_verite":"Le déchu","relations":[],"source_group":"Chasseurs kabbalistes","source_order":43,"identity_keys":["jude riot","juda iscariot judhaniel"],"source_verite":[{"label":"Informations Vérité","text":"Les nephilims désignent ceux qui possède le sang « des fils de dieu » et « des filles des hommes », c’est-à-dire ceux ayant du sang angélique. Autrefois, le Paradis laissa faire les unions entre anges et humains, cela faisait une masse de créatures impossibles à récupérer par les enfers. Cependant, avec le temps, la déesse Astaroth trouva un moyen de libérer leurs âmes de leurs origines biologiques, décomposant « l’arbre de vie » d’Elynea, et posant les futures bases des dons Kabbalistiques. Les Nephilims devinrent une arme à double tranchant, offrant des corps dotés de dons angéliques aux daemons. Si le Déluge n’eut ni lieu à cette époque ni pour cette raison, la purge des nephilims se passa quand même. Face à ce massacre, Judhaniel, un archange, ne parvint pas à tolérer qu’on ne massacre ses descendants, il mena les nephilims dans une ultime rébellion qui favorisa grandement leur purge en vérité, manipulé, à son insu, par l’archange Gabrielle. Bien qu’il fût tué par Michael pour traitrise, l’archange se réveilla dans l’enfer d’Astharoth. La déesse décidant de l’utiliser, le réincarnant encore et encore comme un démon, afin de le voir encore et encore finir par être tué après avoir décidé de trahir son camp, comme coincé dans une boucle de destinée inéluctable. Toujours lié au judaïsme, il ne peut en dévier, mais tôt ou tard, il finit par se sentir déchirer et la « trahison » survient. Jouet des Angelus comme des Daimons, il paye son amour des nephilim en s’incarnant uniquement dans sa propre lignée jusqu’à la mort du dernier. Par son sang Nephilim, son existence actuelle, Jude Riot est un acteur charismatique qui travaille en étroite collaboration avec la réalisatrice Shmira. Il a conscience de ce qu’il est par le journal intime d’un ancêtre, il maitrise les Sephiroth avec une aisance inégalée. Jude pense être le maillon qui brisera sa chaine maudite de souffrance et de trahison, hélas, il n’est pas certain que le journal secret ne soit pas un outil pour le manipuler encore une fois."}],"source_extract":"Jude Riot\nLe déchu\nNom de la Réalité : Jude RIOT\nNom de la Vérité : Juda ISCARIOT/ Judhaniel\nAge : « 25 ans - « ???» ans\nAffiliations :\nchasseurs religieux\nNationalité d’origine : Américaine\nEthnie réelle : Nephilim\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nLes nephilims désignent ceux qui possède le sang « des fils de dieu » et « des filles des hommes »,\nc’est-à-dire ceux ayant du sang angélique.\nAutrefois, le Paradis laissa faire les unions entre anges et humains, cela faisait une masse de\ncréatures impossibles à récupérer par les enfers. Cependant, avec le temps, la déesse Astaroth\ntrouva un moyen de libérer leurs âmes de leurs origines biologiques, décomposant « l’arbre de vie »\nd’Elynea, et posant les futures bases des dons Kabbalistiques. Les Nephilims devinrent une arme à\ndouble tranchant, offrant des corps dotés de dons angéliques aux daemons.\nSi le Déluge n’eut ni lieu à cette époque ni pour cette raison, la purge des nephilims se passa quand\nmême. Face à ce massacre, Judhaniel, un archange, ne parvint pas à tolérer qu’on ne massacre ses\ndescendants, il mena les nephilims dans une ultime rébellion qui favorisa grandement leur purge en\nvérité, manipulé, à son insu, par l’archange Gabrielle.\nBien qu’il fût tué par Michael pour traitrise, l’archange se réveilla dans l’enfer d’Astharoth. La déesse\ndécidant de l’utiliser, le réincarnant encore et encore comme un démon, afin de le voir encore et\nencore finir par être tué après avoir décidé de trahir son camp, comme coincé dans une boucle de\ndestinée inéluctable.\nToujours lié au judaïsme, il ne peut en dévier, mais tôt ou tard, il finit par se sentir déchirer et la\n« trahison » survient. Jouet des Angelus comme des Daimons, il paye son amour des nephilim en\ns’incarnant uniquement dans sa propre lignée jusqu’à la mort du dernier.\nPar son sang Nephilim, son existence actuelle, Jude Riot est un acteur charismatique qui travaille en\nétroite collaboration avec la réalisatrice Shmira.\nIl a conscience de ce qu’il est par le journal intime d’un ancêtre, il maitrise les Sephiroth avec une\naisance inégalée. Jude pense être le maillon qui brisera sa chaine maudite de souffrance et de\ntrahison, hélas, il n’est pas certain que le journal secret ne soit pas un outil pour le manipuler encore\nune fois.","source_heading":"Jude Riot"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Jude RIOT"],["Nom de la Vérité","Juda ISCARIOT/ Judhaniel"],["Âge","« 25 ans - « ???» ans"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","Américaine"],["Nature réelle","Nephilim"],["Repère","Le déchu"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Les nephilims désignent ceux qui possède le sang « des fils de dieu » et « des filles des hommes », c’est-à-dire ceux ayant du sang angélique. Autrefois, le Paradis laissa faire les unions entre anges et humains, cela faisait une masse de créatures impossibles à récupérer par les enfers. Cependant, avec le temps, la déesse Astaroth trouva un moyen de libérer leurs âmes de leurs origines biologiques, décomposant « l’arbre de vie » d’Elynea, et posant les futures bases des dons Kabbalistiques. Les Nephilims devinrent une arme à double tranchant, offrant des corps dotés de dons angéliques aux daemons. Si le Déluge n’eut ni lieu à cette époque ni pour cette raison, la purge des nephilims se passa quand même. Face à ce massacre, Judhaniel, un archange, ne parvint pas à tolérer qu’on ne massacre ses descendants, il mena les nephilims dans une ultime rébellion qui favorisa grandement leur purge en vérité, manipulé, à son insu, par l’archange Gabrielle. Bien qu’il fût tué par Michael pour traitrise, l’archange se réveilla dans l’enfer d’Astharoth. La déesse décidant de l’utiliser, le réincarnant encore et encore comme un démon, afin de le voir encore et encore finir par être tué après avoir décidé de trahir son camp, comme coincé dans une boucle de destinée inéluctable. Toujours lié au judaïsme, il ne peut en dévier, mais tôt ou tard, il finit par se sentir déchirer et la « trahison » survient. Jouet des Angelus comme des Daimons, il paye son amour des nephilim en s’incarnant uniquement dans sa propre lignée jusqu’à la mort du dernier. Par son sang Nephilim, son existence actuelle, Jude Riot est un acteur charismatique qui travaille en étroite collaboration avec la réalisatrice Shmira. Il a conscience de ce qu’il est par le journal intime d’un ancêtre, il maitrise les Sephiroth avec une aisance inégalée. Jude pense être le maillon qui brisera sa chaine maudite de souffrance et de trahison, hélas, il n’est pas certain que le journal secret ne soit pas un outil pour le manipuler encore une fois."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-chafiqa-rhissassi","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Chafiqa Rhissassi","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs kabbalistes","Humaine"],"pnj":{"real_name":"Chafiqa RHISSASSI","nom_verite":"","race":"Humaine","age":"« 30 ans »","origine":"marocaine","statut":"chasseurs religieux","statut_verite":"La chasseuse de démons","relations":[],"source_group":"Chasseurs kabbalistes","source_order":44,"identity_keys":["chafiqa rhissassi"],"source_verite":[{"label":"Informations Vérité","text":"Chafiqa est une juive marocaine, née en 2005 à Marrakech. Elle a débuté sa carrière de mannequin à Paris, en 2025 et depuis, elle n’a pas cessé d’augmenter en notoriété, jusqu’à avoir l’immense honneur d’être l’égérie du mois de février 2035 pour la Tuatha corporation. Cependant, son apparence sulfureuse et sensuelle cache une chasseuse acharnée, une droguée de la traque. Entrainée par des anciens kabbalistes ayant été dans les corps d’élites les plus prestigieux, elle est la chasseuse numéro une de sa confrérie. Contrairement à bien des branches des Kabbalistes, elle ne cherche pas à transcender son existence par la maitrise de l’arbre de vie, elle cherche à en inverser l’utilisation. En effet, elle sacrifie des daemons à chaque Sephira pour augmenter sa maitrise de ces derniers, tous les daemons ainsi prisonniers de son « arbre de vie », elle espère un jour les transformer en angelus par l’inversion dudit arbre de vie. Alors qu’elle n’a que 30 ans, elle est actuellement la Kabbaliste possédant le plus de pouvoirs des dieux démoniaques en elle, véritable bombe à retardement, l’arbre de vie d’Elynea la préserve de l’influence des autres dieux, mais c’est un jeu dangereux qu’elle joue. Elle est détestée par les factions démoniaques, puisqu’elle utilise ses Sephiroth non pas pour en utiliser les pouvoirs mais pour retenir les daemons afin d’utiliser les pouvoirs de ces derniers. La faction angélique la trouve encore plus écœurante que les autres Kabbalistes, les autres chasseurs la perçoivent souvent comme une créature plus qu’une chasseuse car la forme de son aura est celle d’une myriade de corps inhumains fusionnés. Chafiqa est une femme présomptueuse et extrêmement infecte de comportement, elle se pense être une des plus belles femmes au monde et la chasseuse la plus puissante mais derrière cette confiance outrancière, qui donne envie de la corriger, se cachent une tacticienne redoutable jouant bien plus sur ce trait de caractère qu’on ne le pense, sachant très aisément renoncer à toute fierté tant qu’elle peut réussir."}],"source_extract":"Chafiqa Rhissassi\nLa chasseuse de démons\nNom de la Réalité : Chafiqa RHISSASSI\nNom de la Vérité : _\nAge : « 30 ans »\nAffiliations :\nchasseurs religieux\nNationalité d’origine : marocaine\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nChafiqa est une juive marocaine, née en 2005 à Marrakech.\nElle a débuté sa carrière de mannequin à Paris, en 2025 et depuis, elle n’a pas cessé d’augmenter en\nnotoriété, jusqu’à avoir l’immense honneur d’être l’égérie du mois de février 2035 pour la Tuatha\ncorporation.\nCependant, son apparence sulfureuse et sensuelle cache une chasseuse acharnée, une droguée de la\ntraque. Entrainée par des anciens kabbalistes ayant été dans les corps d’élites les plus prestigieux,\nelle est la chasseuse numéro une de sa confrérie.\nContrairement à bien des branches des Kabbalistes, elle ne cherche pas à transcender son existence\npar la maitrise de l’arbre de vie, elle cherche à en inverser l’utilisation. En effet, elle sacrifie des\ndaemons à chaque Sephira pour augmenter sa maitrise de ces derniers, tous les daemons ainsi\nprisonniers de son « arbre de vie », elle espère un jour les transformer en angelus par l’inversion\ndudit arbre de vie.\nAlors qu’elle n’a que 30 ans, elle est actuellement la Kabbaliste possédant le plus de pouvoirs des\ndieux démoniaques en elle, véritable bombe à retardement, l’arbre de vie d’Elynea la préserve de\nl’influence des autres dieux, mais c’est un jeu dangereux qu’elle joue.\nElle est détestée par les factions démoniaques, puisqu’elle utilise ses Sephiroth non pas pour en\nutiliser les pouvoirs mais pour retenir les daemons afin d’utiliser les pouvoirs de ces derniers. La\nfaction angélique la trouve encore plus écœurante que les autres Kabbalistes, les autres chasseurs la\nperçoivent souvent comme une créature plus qu’une chasseuse car la forme de son aura est celle\nd’une myriade de corps inhumains fusionnés.\nChafiqa est une femme présomptueuse et extrêmement infecte de comportement, elle se pense être\nune des plus belles femmes au monde et la chasseuse la plus puissante mais derrière cette confiance\noutrancière, qui donne envie de la corriger, se cachent une tacticienne redoutable jouant bien plus\nsur ce trait de caractère qu’on ne le pense, sachant très aisément renoncer à toute fierté tant qu’elle\npeut réussir.","source_heading":"Chafiqa Rhissassi"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Chafiqa RHISSASSI"],["Nom de la Vérité","_"],["Âge","« 30 ans »"],["Affiliations","chasseurs religieux"],["Nationalité d’origine","marocaine"],["Nature réelle","Humaine"],["Repère","La chasseuse de démons"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Chafiqa est une juive marocaine, née en 2005 à Marrakech. Elle a débuté sa carrière de mannequin à Paris, en 2025 et depuis, elle n’a pas cessé d’augmenter en notoriété, jusqu’à avoir l’immense honneur d’être l’égérie du mois de février 2035 pour la Tuatha corporation. Cependant, son apparence sulfureuse et sensuelle cache une chasseuse acharnée, une droguée de la traque. Entrainée par des anciens kabbalistes ayant été dans les corps d’élites les plus prestigieux, elle est la chasseuse numéro une de sa confrérie. Contrairement à bien des branches des Kabbalistes, elle ne cherche pas à transcender son existence par la maitrise de l’arbre de vie, elle cherche à en inverser l’utilisation. En effet, elle sacrifie des daemons à chaque Sephira pour augmenter sa maitrise de ces derniers, tous les daemons ainsi prisonniers de son « arbre de vie », elle espère un jour les transformer en angelus par l’inversion dudit arbre de vie. Alors qu’elle n’a que 30 ans, elle est actuellement la Kabbaliste possédant le plus de pouvoirs des dieux démoniaques en elle, véritable bombe à retardement, l’arbre de vie d’Elynea la préserve de l’influence des autres dieux, mais c’est un jeu dangereux qu’elle joue. Elle est détestée par les factions démoniaques, puisqu’elle utilise ses Sephiroth non pas pour en utiliser les pouvoirs mais pour retenir les daemons afin d’utiliser les pouvoirs de ces derniers. La faction angélique la trouve encore plus écœurante que les autres Kabbalistes, les autres chasseurs la perçoivent souvent comme une créature plus qu’une chasseuse car la forme de son aura est celle d’une myriade de corps inhumains fusionnés. Chafiqa est une femme présomptueuse et extrêmement infecte de comportement, elle se pense être une des plus belles femmes au monde et la chasseuse la plus puissante mais derrière cette confiance outrancière, qui donne envie de la corriger, se cachent une tacticienne redoutable jouant bien plus sur ce trait de caractère qu’on ne le pense, sachant très aisément renoncer à toute fierté tant qu’elle peut réussir."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-daryl-graves","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Daryl Graves","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Confréries","Humaine"],"pnj":{"real_name":"Daryl Graves","nom_verite":"« Yvain le Preux »","race":"Humaine","age":"« 45 ans - _","origine":"Britannique","statut":"chasseurs de confrérie","statut_verite":"Chasseur de La table Ronde","relations":[],"source_group":"Confréries","source_order":45,"identity_keys":["daryl graves","yvain le preux"],"source_verite":[{"label":"Informations Vérité","text":"Les « chevaliers de la table Ronde » sont les membres d’une confrérie de chasseurs qui se démarquent des autres confréries. Le véritable objectif de ces chasseurs sont non pas les créatures mais les trésors, reliques et vestiges qu’elles peuvent posséder, défendre ou bien dissimuler. A l’instar de la Quête du Saint Graal, les légendes arthuriennes laissent entrevoir plusieurs aventures de la première « table ronde ». Tout débuta quand Merlin, le plus grand archimage né humain, décida de non pas s’entourer de sorciers mais de chevaliers les plus braves de l’archipel britannique, instaurant Arthur comme roi. Il leur façonna de l’équipement et leur trouva des montures ou des familiers pour accomplir leurs Quêtes. Un siècle après la mort d’Arthur, Merlin reforma une table ronde, il trouva de jeunes preux, qui furent acceptés par les armes chevaleresques des premiers chevaliers, ils en obtinrent les titres et les habilités au combat, ainsi naquit la « Table Ronde » en tant que confrérie secrète, continuant d’amasser les saints trésors. Daryl GRAVES était un membre de Blackwater une compagnie mercenaire que finit par diriger Liam O Siridean, un des plus terribles guerriers modernes quand en 2022, à 32 ans, son corps fut broyé par des débris à la suite d’un bombardement russe visant les Nord-coréens mais touchant les mercenaires massivement déployés par les Etats-Unis et ses alliés afin de gagner du temps pour la reconstruction de son armée. Sauvé par un type étrange se battant avec une épée en pleine guerre de 2022, le mercenaire n’y comprit rien, son corps était brisé l’instant d’avant et était plus forts après avoir été touché par le fourreau qu’on posa sur lui. Il aida l’inconnu à accéder à une base nord￾coréenne où ce dernier récupéra un fragment de métal étrange qu’il planta dans le cœur de Daryl, quand Daryl se réveilla, l’inconnu le nommait « Yvain » et le ramena en Angleterre où il intégra la confrérie secrète, découvrant de terribles secrets sur le monde, tels que les elfes complotant contre les humains ou de terribles créatures de ténèbres, se voyant capable de manier « l’épée du lion », Daryl avait obtenu le titre du Chevalier arthurien, Yvain. En 2035, « Yvain » est désormais la tête de la « Table Ronde », il commande à quatre chevaliers seulement : « Keu », « Tristan », « Perceval » et « Gareth ». Il cherche les héritiers spirituels des autres chevaliers mais surtout « Arthur », le roi. L’inconnu serait un sorcier, un ancien serviteur de Merlin."}],"source_extract":"Daryl Graves\nChasseur de La table Ronde\nNom de la Réalité : Daryl Graves\nNom de la Vérité : « Yvain le Preux »\nAge : « 45 ans - _\nAffiliations :\nchasseurs de confrérie\nNationalité d’origine : Britannique\nEthnie réelle : Humaine\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nLes « chevaliers de la table Ronde » sont les membres d’une confrérie de chasseurs qui se\ndémarquent des autres confréries. Le véritable objectif de ces chasseurs sont non pas les créatures\nmais les trésors, reliques et vestiges qu’elles peuvent posséder, défendre ou bien dissimuler. A\nl’instar de la Quête du Saint Graal, les légendes arthuriennes laissent entrevoir plusieurs aventures\nde la première « table ronde ». Tout débuta quand Merlin, le plus grand archimage né humain,\ndécida de non pas s’entourer de sorciers mais de chevaliers les plus braves de l’archipel britannique,\ninstaurant Arthur comme roi. Il leur façonna de l’équipement et leur trouva des montures ou des\nfamiliers pour accomplir leurs Quêtes. Un siècle après la mort d’Arthur, Merlin reforma une table\nronde, il trouva de jeunes preux, qui furent acceptés par les armes chevaleresques des premiers\nchevaliers, ils en obtinrent les titres et les habilités au combat, ainsi naquit la « Table Ronde » en tant\nque confrérie secrète, continuant d’amasser les saints trésors.\nDaryl GRAVES était un membre de Blackwater une compagnie mercenaire que finit par diriger Liam O\nSiridean, un des plus terribles guerriers modernes quand en 2022, à 32 ans, son corps fut broyé par\ndes débris à la suite d’un bombardement russe visant les Nord-coréens mais touchant les\nmercenaires massivement déployés par les Etats-Unis et ses alliés afin de gagner du temps pour la\nreconstruction de son armée. Sauvé par un type étrange se battant avec une épée en pleine guerre\nde 2022, le mercenaire n’y comprit rien, son corps était brisé l’instant d’avant et était plus forts après\navoir été touché par le fourreau qu’on posa sur lui. Il aida l’inconnu à accéder à une base nord￾coréenne où ce dernier récupéra un fragment de métal étrange qu’il planta dans le cœur de Daryl,\nquand Daryl se réveilla, l’inconnu le nommait « Yvain » et le ramena en Angleterre où il intégra la\nconfrérie secrète, découvrant de terribles secrets sur le monde, tels que les elfes complotant contre\nles humains ou de terribles créatures de ténèbres, se voyant capable de manier « l’épée du lion »,\nDaryl avait obtenu le titre du Chevalier arthurien, Yvain.\nEn 2035, « Yvain » est désormais la tête de la « Table Ronde », il commande à quatre chevaliers\nseulement : « Keu », « Tristan », « Perceval » et « Gareth ». Il cherche les héritiers spirituels des\nautres chevaliers mais surtout « Arthur », le roi. L’inconnu serait un sorcier, un ancien serviteur de\nMerlin.","source_heading":"Daryl Graves"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Daryl Graves"],["Nom de la Vérité","« Yvain le Preux »"],["Âge","« 45 ans - _"],["Affiliations","chasseurs de confrérie"],["Nationalité d’origine","Britannique"],["Nature réelle","Humaine"],["Repère","Chasseur de La table Ronde"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Les « chevaliers de la table Ronde » sont les membres d’une confrérie de chasseurs qui se démarquent des autres confréries. Le véritable objectif de ces chasseurs sont non pas les créatures mais les trésors, reliques et vestiges qu’elles peuvent posséder, défendre ou bien dissimuler. A l’instar de la Quête du Saint Graal, les légendes arthuriennes laissent entrevoir plusieurs aventures de la première « table ronde ». Tout débuta quand Merlin, le plus grand archimage né humain, décida de non pas s’entourer de sorciers mais de chevaliers les plus braves de l’archipel britannique, instaurant Arthur comme roi. Il leur façonna de l’équipement et leur trouva des montures ou des familiers pour accomplir leurs Quêtes. Un siècle après la mort d’Arthur, Merlin reforma une table ronde, il trouva de jeunes preux, qui furent acceptés par les armes chevaleresques des premiers chevaliers, ils en obtinrent les titres et les habilités au combat, ainsi naquit la « Table Ronde » en tant que confrérie secrète, continuant d’amasser les saints trésors. Daryl GRAVES était un membre de Blackwater une compagnie mercenaire que finit par diriger Liam O Siridean, un des plus terribles guerriers modernes quand en 2022, à 32 ans, son corps fut broyé par des débris à la suite d’un bombardement russe visant les Nord-coréens mais touchant les mercenaires massivement déployés par les Etats-Unis et ses alliés afin de gagner du temps pour la reconstruction de son armée. Sauvé par un type étrange se battant avec une épée en pleine guerre de 2022, le mercenaire n’y comprit rien, son corps était brisé l’instant d’avant et était plus forts après avoir été touché par le fourreau qu’on posa sur lui. Il aida l’inconnu à accéder à une base nord￾coréenne où ce dernier récupéra un fragment de métal étrange qu’il planta dans le cœur de Daryl, quand Daryl se réveilla, l’inconnu le nommait « Yvain » et le ramena en Angleterre où il intégra la confrérie secrète, découvrant de terribles secrets sur le monde, tels que les elfes complotant contre les humains ou de terribles créatures de ténèbres, se voyant capable de manier « l’épée du lion », Daryl avait obtenu le titre du Chevalier arthurien, Yvain. En 2035, « Yvain » est désormais la tête de la « Table Ronde », il commande à quatre chevaliers seulement : « Keu », « Tristan », « Perceval » et « Gareth ». Il cherche les héritiers spirituels des autres chevaliers mais surtout « Arthur », le roi. L’inconnu serait un sorcier, un ancien serviteur de Merlin."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-gunhild-wollen","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Gunhild Wollen","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Confréries","humaine ( ?)"],"pnj":{"real_name":"Gunhild WOLLEN","nom_verite":"","race":"humaine ( ?)","age":"«24 ans » - ???","origine":"Norvégienne","statut":"chasseurs de confrérie","statut_verite":"Les chasseurs de Fenrir","relations":[],"source_group":"Confréries","source_order":46,"identity_keys":["gunhild wollen"],"source_verite":[{"label":"Informations Vérité","text":"Gunhild est une chasseuse de l’ordre des « chasseurs de Fenrir », bien qu’assez jeune, avec ses 24 ans, elle est la « première Valkyrie de l’ordre », un ordre essentiellement féminin servant le dieu néopaïen Odin. Cet ordre est ancien, il puise ses racines durant l’antiquité, notamment durant les insertions des Goths dans l’empire romain. Cet ordre ne chasse que deux types d’ennemis : les spectres et les loups-garous, les chasseuses de l’ordre de Fenrir n’ont rien à faire du reste. Dans leur croyance, les loups-garous descendent de Fenrir, le fils de Loki, ils sont les héritiers du sang du dieu trompeur et œuvrent pour le Ragnarök. Les fantômes quant à eux sont les armées de Hel, la déesse de la Mort qu’elle enverrait en avance du Ragnarök. Gunhild était la fille de Ronnaug, qui fut tuée par Thorunn, la Meneuse des pelages blancs, le « clan » loup-garou que cette confrérie chasse et combat depuis toujours. Cependant, quelques rumeurs dans la confrérie laisseraient entendre que Gunhild serait une fille de Thorunn que Ronnaug avait épargnée et enlevée comme un atout secret. Gunhild ne semble pas posséder de don exprimé qui viendrait d’une ascendance garou, en revanche, absolument cruelle et impitoyable, elle est bien plus sanguinaire que sa mère et aurait mené Thorunn à fuir aux Etats-unis en s’alliant à une inconnue nommée Charunee. Gunhild est connue pour son agressivité effrayante, c’est un pilote émérite qui possède un eurocopter EC665 tigre lourdement modifié et modernisé notamment avec un pilotage autonome lui permettant de pouvoir attaque presque n’importe où avec un appui aérien. Elle-même est une guerrière comme très peu d’humains en sont, ses instincts sont sa force mais elle n’a pas regardé à la dépense pour modifier son corps, offrant à ses instincts surhumains des sens l’étant tout autant et des membres ayant la puissance suffisante pour maitriser des garous dans leur forme la plus déchainée même au corps à corps."}],"source_extract":"Gunhild Wollen\nLes chasseurs de Fenrir\nNom de la Réalité : Gunhild WOLLEN\nNom de la Vérité : _\nAge : «24 ans » - ???\nAffiliations :\nchasseurs de confrérie\nNationalité d’origine : Norvégienne\nEthnie réelle : humaine ( ?)\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations vérité :\nGunhild est une chasseuse de l’ordre des « chasseurs de Fenrir », bien qu’assez jeune, avec ses 24\nans, elle est la « première Valkyrie de l’ordre », un ordre essentiellement féminin servant le dieu\nnéopaïen Odin.\nCet ordre est ancien, il puise ses racines durant l’antiquité, notamment durant les insertions des\nGoths dans l’empire romain.\nCet ordre ne chasse que deux types d’ennemis : les spectres et les loups-garous, les chasseuses de\nl’ordre de Fenrir n’ont rien à faire du reste. Dans leur croyance, les loups-garous descendent de\nFenrir, le fils de Loki, ils sont les héritiers du sang du dieu trompeur et œuvrent pour le Ragnarök.\nLes fantômes quant à eux sont les armées de Hel, la déesse de la Mort qu’elle enverrait en avance\ndu Ragnarök.\nGunhild était la fille de Ronnaug, qui fut tuée par Thorunn, la Meneuse des pelages blancs, le « clan »\nloup-garou que cette confrérie chasse et combat depuis toujours. Cependant, quelques rumeurs\ndans la confrérie laisseraient entendre que Gunhild serait une fille de Thorunn que Ronnaug avait\népargnée et enlevée comme un atout secret.\nGunhild ne semble pas posséder de don exprimé qui viendrait d’une ascendance garou, en revanche,\nabsolument cruelle et impitoyable, elle est bien plus sanguinaire que sa mère et aurait mené\nThorunn à fuir aux Etats-unis en s’alliant à une inconnue nommée Charunee.\nGunhild est connue pour son agressivité effrayante, c’est un pilote émérite qui possède un\neurocopter EC665 tigre lourdement modifié et modernisé notamment avec un pilotage autonome lui\npermettant de pouvoir attaque presque n’importe où avec un appui aérien.\nElle-même est une guerrière comme très peu d’humains en sont, ses instincts sont sa force mais elle\nn’a pas regardé à la dépense pour modifier son corps, offrant à ses instincts surhumains des sens\nl’étant tout autant et des membres ayant la puissance suffisante pour maitriser des garous dans leur\nforme la plus déchainée même au corps à corps.","source_heading":"Gunhild Wollen"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Gunhild WOLLEN"],["Nom de la Vérité","_"],["Âge","«24 ans » - ???"],["Affiliations","chasseurs de confrérie"],["Nationalité d’origine","Norvégienne"],["Nature réelle","humaine ( ?)"],["Repère","Les chasseurs de Fenrir"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Gunhild est une chasseuse de l’ordre des « chasseurs de Fenrir », bien qu’assez jeune, avec ses 24 ans, elle est la « première Valkyrie de l’ordre », un ordre essentiellement féminin servant le dieu néopaïen Odin. Cet ordre est ancien, il puise ses racines durant l’antiquité, notamment durant les insertions des Goths dans l’empire romain. Cet ordre ne chasse que deux types d’ennemis : les spectres et les loups-garous, les chasseuses de l’ordre de Fenrir n’ont rien à faire du reste. Dans leur croyance, les loups-garous descendent de Fenrir, le fils de Loki, ils sont les héritiers du sang du dieu trompeur et œuvrent pour le Ragnarök. Les fantômes quant à eux sont les armées de Hel, la déesse de la Mort qu’elle enverrait en avance du Ragnarök. Gunhild était la fille de Ronnaug, qui fut tuée par Thorunn, la Meneuse des pelages blancs, le « clan » loup-garou que cette confrérie chasse et combat depuis toujours. Cependant, quelques rumeurs dans la confrérie laisseraient entendre que Gunhild serait une fille de Thorunn que Ronnaug avait épargnée et enlevée comme un atout secret. Gunhild ne semble pas posséder de don exprimé qui viendrait d’une ascendance garou, en revanche, absolument cruelle et impitoyable, elle est bien plus sanguinaire que sa mère et aurait mené Thorunn à fuir aux Etats-unis en s’alliant à une inconnue nommée Charunee. Gunhild est connue pour son agressivité effrayante, c’est un pilote émérite qui possède un eurocopter EC665 tigre lourdement modifié et modernisé notamment avec un pilotage autonome lui permettant de pouvoir attaque presque n’importe où avec un appui aérien. Elle-même est une guerrière comme très peu d’humains en sont, ses instincts sont sa force mais elle n’a pas regardé à la dépense pour modifier son corps, offrant à ses instincts surhumains des sens l’étant tout autant et des membres ayant la puissance suffisante pour maitriser des garous dans leur forme la plus déchainée même au corps à corps."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-aymn-salib","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Amunthoris","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Confréries","« momie »"],"pnj":{"real_name":"Aymn SALIB","nom_verite":"Amunthosis","race":"« momie »","age":"« 51 ans » - 5129 ans","origine":"égyptienne","statut":"chasseurs des confréries","statut_verite":"Les chasseurs d’Osiris","relations":[],"source_group":"Confréries","source_order":47,"identity_keys":["amunthoris","aymn salib","amunthosis"],"source_verite":[{"label":"Informations Vérité","text":"Le docteur en neuro-psychanalyse, Aym SALIB est une référence dans le domaine médicale pour tout ce qui concerne le cerveau et les maladies mentales. Sa dernière publication sur les augmentations lui a valu d’être lynché dans une ruelle de Los Angeles par des fanatiques de l’Eglise Cyber. Toutefois, de simples mortels auraient eu bien du mal à massacrer le grand prêtre d’Osiris (Mammon) impunément. En effet, bien qu’il ne le revendique pas, Aymn est la principale figure du néopaganisme égyptien mais plus encore, il est aussi le grand prêtre d’Osiris et à ce titre, il commande à la confrérie des chasseurs qui y est associée. Amunthosis est un prêtre très ancien de l’Egypte antique, à sa mort, il a été momifié selon les rites de l’époque. Pendant le règne ottoman en 1517 notamment, à la chute des mamelouks d’Egypte, sa tombe a été ouverte par les chasseurs de la secte qu’il avait fondé. Ils prirent son corps et le ravivèrent selon les écrits qu’il leur avait légué. Il ne faut toutefois pas voir Amunthosis comme un mauvais plagiat des films de momies, une fois ranimé, il fut mortel à nouveau et sa volonté ne fut que de défendre les intérêts des dieux anciens. Les plus grands ennemis de son ordre de chasseurs sont les morts-vivants, non-morts et autres anciens humains refusant de se soumettre à l’ordre divin qu’est le cycle de la vie. Chasseurs de fantôme et de zombies, ses partisans sont des tueurs de créatures mortes. Tous les deux siècles, ils réaniment Amunthosis pour qu’il n’enchante leurs lames rituelles et ne désigne les cibles à abattre. En soi, Amunthosis ne chasse pas souvent lui-même, bien que mortel à chaque fois qu’on ravive la flamme de son existence, il semble capable de dévorer l’énergie vitale à distance, comme certains vampires, ceci lui permettant de régénérer de ses blessures, mais pour y parvenir, il doit blesser à l’aide de sa dague rituelle et seulement d’elle. Néopaïen convaincu dans la Réalité, il ne craint pas de provoquer la colère des monothéistes en soulignant tout ce que leurs légendes ont dérobé aux cultes polythéistes, ce qui lui vaut d’être considéré comme un des pires antisémites de 2035."}],"source_extract":"Amunthoris\nLes chasseurs d’Osiris\nNom de la Réalité : Aymn SALIB\nNom de la Vérité : Amunthosis\nAge : « 51 ans » - 5129 ans\nAffiliations :\nchasseurs des confréries\nNationalité d’origine : égyptienne\nEthnie réelle : « momie »\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\nLe docteur en neuro-psychanalyse, Aym SALIB est une référence dans le domaine médicale pour tout\nce qui concerne le cerveau et les maladies mentales. Sa dernière publication sur les augmentations\nlui a valu d’être lynché dans une ruelle de Los Angeles par des fanatiques de l’Eglise Cyber.\nToutefois, de simples mortels auraient eu bien du mal à massacrer le grand prêtre d’Osiris\n(Mammon) impunément. En effet, bien qu’il ne le revendique pas, Aymn est la principale figure du\nnéopaganisme égyptien mais plus encore, il est aussi le grand prêtre d’Osiris et à ce titre, il\ncommande à la confrérie des chasseurs qui y est associée.\nAmunthosis est un prêtre très ancien de l’Egypte antique, à sa mort, il a été momifié selon les rites de\nl’époque.\nPendant le règne ottoman en 1517 notamment, à la chute des mamelouks d’Egypte, sa tombe a été\nouverte par les chasseurs de la secte qu’il avait fondé. Ils prirent son corps et le ravivèrent selon les\nécrits qu’il leur avait légué.\nIl ne faut toutefois pas voir Amunthosis comme un mauvais plagiat des films de momies, une fois\nranimé, il fut mortel à nouveau et sa volonté ne fut que de défendre les intérêts des dieux anciens.\nLes plus grands ennemis de son ordre de chasseurs sont les morts-vivants, non-morts et autres\nanciens humains refusant de se soumettre à l’ordre divin qu’est le cycle de la vie. Chasseurs de\nfantôme et de zombies, ses partisans sont des tueurs de créatures mortes.\nTous les deux siècles, ils réaniment Amunthosis pour qu’il n’enchante leurs lames rituelles et ne\ndésigne les cibles à abattre.\nEn soi, Amunthosis ne chasse pas souvent lui-même, bien que mortel à chaque fois qu’on ravive la\nflamme de son existence, il semble capable de dévorer l’énergie vitale à distance, comme certains\nvampires, ceci lui permettant de régénérer de ses blessures, mais pour y parvenir, il doit blesser à\nl’aide de sa dague rituelle et seulement d’elle.\nNéopaïen convaincu dans la Réalité, il ne craint pas de provoquer la colère des monothéistes en\nsoulignant tout ce que leurs légendes ont dérobé aux cultes polythéistes, ce qui lui vaut d’être\nconsidéré comme un des pires antisémites de 2035.","source_heading":"Amunthoris"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Aymn SALIB"],["Nom de la Vérité","Amunthosis"],["Âge","« 51 ans » - 5129 ans"],["Affiliations","chasseurs des confréries"],["Nationalité d’origine","égyptienne"],["Nature réelle","« momie »"],["Repère","Les chasseurs d’Osiris"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"Le docteur en neuro-psychanalyse, Aym SALIB est une référence dans le domaine médicale pour tout ce qui concerne le cerveau et les maladies mentales. Sa dernière publication sur les augmentations lui a valu d’être lynché dans une ruelle de Los Angeles par des fanatiques de l’Eglise Cyber. Toutefois, de simples mortels auraient eu bien du mal à massacrer le grand prêtre d’Osiris (Mammon) impunément. En effet, bien qu’il ne le revendique pas, Aymn est la principale figure du néopaganisme égyptien mais plus encore, il est aussi le grand prêtre d’Osiris et à ce titre, il commande à la confrérie des chasseurs qui y est associée. Amunthosis est un prêtre très ancien de l’Egypte antique, à sa mort, il a été momifié selon les rites de l’époque. Pendant le règne ottoman en 1517 notamment, à la chute des mamelouks d’Egypte, sa tombe a été ouverte par les chasseurs de la secte qu’il avait fondé. Ils prirent son corps et le ravivèrent selon les écrits qu’il leur avait légué. Il ne faut toutefois pas voir Amunthosis comme un mauvais plagiat des films de momies, une fois ranimé, il fut mortel à nouveau et sa volonté ne fut que de défendre les intérêts des dieux anciens. Les plus grands ennemis de son ordre de chasseurs sont les morts-vivants, non-morts et autres anciens humains refusant de se soumettre à l’ordre divin qu’est le cycle de la vie. Chasseurs de fantôme et de zombies, ses partisans sont des tueurs de créatures mortes. Tous les deux siècles, ils réaniment Amunthosis pour qu’il n’enchante leurs lames rituelles et ne désigne les cibles à abattre. En soi, Amunthosis ne chasse pas souvent lui-même, bien que mortel à chaque fois qu’on ravive la flamme de son existence, il semble capable de dévorer l’énergie vitale à distance, comme certains vampires, ceci lui permettant de régénérer de ses blessures, mais pour y parvenir, il doit blesser à l’aide de sa dague rituelle et seulement d’elle. Néopaïen convaincu dans la Réalité, il ne craint pas de provoquer la colère des monothéistes en soulignant tout ce que leurs légendes ont dérobé aux cultes polythéistes, ce qui lui vaut d’être considéré comme un des pires antisémites de 2035."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-stephania-volkov","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Stephania Volkov","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Confréries","humaine"],"pnj":{"real_name":"Stephania VOLKOV","nom_verite":"","race":"humaine","age":"«41 ans »","origine":"russe","statut":"chasseurs des confrérie","statut_verite":"L’ordre de longinus","relations":["Levanah URIEL","Catalina de la CAZA"],"source_group":"Confréries","source_order":48,"identity_keys":["stephania volkov"],"source_verite":[],"source_extract":"Stephania Volkov\nL’ordre de longinus\nNom de la Réalité : Stephania VOLKOV\nNom de la Vérité : _\nAge : «41 ans »\n-\nAffiliations :\nchasseurs des confrérie\nNationalité d’origine : russe\nEthnie réelle : humaine\nPersonnages liés :\n Levanah URIEL\n Catalina de la CAZA\n___________________________________________________________________________\nInformations Réalité :\nL’ordre de Longinus est un ancien ordre Chrétien qui refusa de se plier aux réformes papales\nimposant la fusion avec les autres ordres de chasseurs de l’Eglise.\nAprès le schisme menant à ce que cet ordre soit considéré comme hérétique par les Catholiques,\nl’ordre s’installa en territoire orthodoxe où il fut toléré. L’ordre considère que seul celui possédant la\nsainte Lance de Longin possède le droit de se réclamer souverain pontife, ainsi l’ordre possède son\n« pape d’or et d’ombres » et considère à la base les protestants et catholiques comme les véritables\nhérétiques, épargnant les orthodoxes, hélas depuis la fusion des chrétiens, l’ordre est seul contre\nune chrétienté dévoyée et abusée, considérant Innocentia comme la « Diablesse ».\nL’ordre est sensiblement comparable aux chasseurs Chrétiens, il en utilise les codes actuels, les\nméthodes et nombre de techniques. Il puise dans tous les ordres de chasseurs que la Chrétienté a\nchassé et désavoué, repêchant ceux des Saintes Lagunes par exemple, récemment, ou bien les\ntempliers et bien d’autres, possédant un socle de guerrier et croyant extrêmement farouches.\n« L’ombre-Pape » a désigné le nouveau Messie en la personne d’une ancienne sorcière des saintes\nlagunes, Stephania VOLKOV, que l’ordre sauva d’une mort certaine quand Alisa ( Ux’Sharith ) Fléau\nincarné, retira son essence de son corps.\nBien que Stephania ne sache pas en quoi ni pourquoi, elle fut placée à la tête de l’ordre et reçu la\nlance de Longin comme présent afin qu’elle ne tue la « Papesse des enfers », Innocentia. Poussée par\nses bienfaiteurs, Stephania ne peut reculer et a accepté de puiser dans leurs pouvoirs dont elle sent\nune étrange similarité avec ceux des sorcières qu’elle chassait et qu’elle était autrefois.\nServant à son insu le Fléau Mloxol v'aagor et son avatar, « l’ombre-pape », stephania ne peut se\nsoustraire à l’influence monstrueuse de son maitre, marquée depuis sa naissance par Ux’Sharith,\nl’âme de Stephania est comme contrainte par essence de se soumettre aux Fléaux bien qu’elle en\nsoit dégoutée.\nPratiquement ressuscitée pour devenir la meneuse de cet ordre, Stephania est incroyablement plus\npuissante qu’autrefois et, forcément, chasse uniquement les chasseurs Monothéïstes.","source_heading":"Stephania Volkov"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","Stephania VOLKOV"],["Nom de la Vérité","_"],["Âge","«41 ans »"],["Affiliations","chasseurs des confrérie"],["Nationalité d’origine","russe"],["Nature réelle","humaine"],["Personnages liés","Levanah URIEL · Catalina de la CAZA"],["Repère","L’ordre de longinus"]]}]},{"id":"chasseurs-informations-realite","title":"Informations Réalité — dossier Chasseurs","level":2,"blocks":[{"type":"p","text":"L’ordre de Longinus est un ancien ordre Chrétien qui refusa de se plier aux réformes papales imposant la fusion avec les autres ordres de chasseurs de l’Eglise. Après le schisme menant à ce que cet ordre soit considéré comme hérétique par les Catholiques, l’ordre s’installa en territoire orthodoxe où il fut toléré. L’ordre considère que seul celui possédant la sainte Lance de Longin possède le droit de se réclamer souverain pontife, ainsi l’ordre possède son « pape d’or et d’ombres » et considère à la base les protestants et catholiques comme les véritables hérétiques, épargnant les orthodoxes, hélas depuis la fusion des chrétiens, l’ordre est seul contre une chrétienté dévoyée et abusée, considérant Innocentia comme la « Diablesse ». L’ordre est sensiblement comparable aux chasseurs Chrétiens, il en utilise les codes actuels, les méthodes et nombre de techniques. Il puise dans tous les ordres de chasseurs que la Chrétienté a chassé et désavoué, repêchant ceux des Saintes Lagunes par exemple, récemment, ou bien les templiers et bien d’autres, possédant un socle de guerrier et croyant extrêmement farouches. « L’ombre-Pape » a désigné le nouveau Messie en la personne d’une ancienne sorcière des saintes lagunes, Stephania VOLKOV, que l’ordre sauva d’une mort certaine quand Alisa ( Ux’Sharith ) Fléau incarné, retira son essence de son corps. Bien que Stephania ne sache pas en quoi ni pourquoi, elle fut placée à la tête de l’ordre et reçu la lance de Longin comme présent afin qu’elle ne tue la « Papesse des enfers », Innocentia. Poussée par ses bienfaiteurs, Stephania ne peut reculer et a accepté de puiser dans leurs pouvoirs dont elle sent une étrange similarité avec ceux des sorcières qu’elle chassait et qu’elle était autrefois. Servant à son insu le Fléau Mloxol v'aagor et son avatar, « l’ombre-pape », stephania ne peut se soustraire à l’influence monstrueuse de son maitre, marquée depuis sa naissance par Ux’Sharith, l’âme de Stephania est comme contrainte par essence de se soumettre aux Fléaux bien qu’elle en soit dégoutée. Pratiquement ressuscitée pour devenir la meneuse de cet ordre, Stephania est incroyablement plus puissante qu’autrefois et, forcément, chasse uniquement les chasseurs Monothéïstes."}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]},{"id":"personnages-verite-chasseurs-gong-min-ju","dataset":"verite-hunters-pnj","category":"Personnages","sourceCategory":"Personnages","title":"Ral’var IV","source":"TUC_Vérité_ les chasseurs(1).docx","status":"canon_source","rebuildV2":true,"tags":["Vérité","Chasseurs","Chasseurs extraterrestres","Tallasse"],"pnj":{"real_name":"GONG Min-Ju","nom_verite":"Ral’var IV","race":"Tallasse","age":"« 25 ans « - ?? ans","origine":"Nord-coréenne","statut":"chasseurs alien","statut_verite":"Chasseur de l’Emeraude Sanglante","relations":[],"source_group":"Chasseurs extraterrestres","source_order":49,"identity_keys":["ral'var iv","gong min ju"],"source_verite":[{"label":"Informations Vérité","text":"« L’émeraude sanglante » compte de nombreux combattants d’élite qui n’ont rien à envier aux plus grands héros humains. Ral’var IV en est le meilleur exemple, loyal bras droit du général Saoden, ce terroriste a déjà envoyé voler deux fois de suite A-man qui tenta de l’arrêter. Son armure est un modèle custom de « Malbeol II » (frelon en coréen) dont la principale fonction est de lui conférer la résistance et la force que les talass n’ont pas afin de mettre à contribution leurs réflexes et leur agilité prodigieuse. Ral’var est plus réputé encore sur le champ de bataille que Saoden en personne et c’est pourquoi il est le plus célèbre des « Emeraldiens » chasseurs. Il a beaucoup de mal à s’intégrer dans la Réalité, ayant opté pour une apparence de jeune homme séduisant pour se donner plus de chances de sembler normal, on le confond avec des personnalités connues, subissant un harcèlement constant des groupies d’un groupe de K-pop dont un des membres est son sosie. C’est un handicapé social qui n’a aucun talent pour les interactions n’étant pas guerrières, tactiques et bien organisées. Sa cible prioritaire est Tejana (Nel’Akna), qu’il considère être une grande menace mais il organise depuis plusieurs années l’anéantissement du Xenoshield, qu’il ne supporte pas. Hélas pour lui, Saoden apprécie utiliser les humains de cette organisation pour acculer des cibles sans mobiliser le moindre guerrier, ce qui a tendance à créer des tensions dans l’armée de « L’émeraude sanglante »."}],"source_extract":"Ral’var IV\nChasseur de l’Emeraude Sanglante\nNom de la Réalité : GONG Min-Ju\nNom de la Vérité : Ral’var IV\nAge : « 25 ans « - ?? ans\nAffiliations :\nchasseurs alien\nNationalité d’origine : Nord-coréenne\nEthnie réelle : Tallasse\nPersonnages liés :\n ?\n ?\n___________________________________________________________________________\nInformations Vérité :\n« L’émeraude sanglante » compte de nombreux combattants d’élite qui n’ont rien à envier aux plus\ngrands héros humains.\nRal’var IV en est le meilleur exemple, loyal bras droit du général Saoden, ce terroriste a déjà envoyé\nvoler deux fois de suite A-man qui tenta de l’arrêter.\nSon armure est un modèle custom de « Malbeol II » (frelon en coréen) dont la principale fonction est\nde lui conférer la résistance et la force que les talass n’ont pas afin de mettre à contribution leurs\nréflexes et leur agilité prodigieuse.\nRal’var est plus réputé encore sur le champ de bataille que Saoden en personne et c’est pourquoi il\nest le plus célèbre des « Emeraldiens » chasseurs.\nIl a beaucoup de mal à s’intégrer dans la Réalité, ayant opté pour une apparence de jeune homme\nséduisant pour se donner plus de chances de sembler normal, on le confond avec des personnalités\nconnues, subissant un harcèlement constant des groupies d’un groupe de K-pop dont un des\nmembres est son sosie. C’est un handicapé social qui n’a aucun talent pour les interactions n’étant\npas guerrières, tactiques et bien organisées.\nSa cible prioritaire est Tejana (Nel’Akna), qu’il considère être une grande menace mais il organise\ndepuis plusieurs années l’anéantissement du Xenoshield, qu’il ne supporte pas.\nHélas pour lui, Saoden apprécie utiliser les humains de cette organisation pour acculer des cibles\nsans mobiliser le moindre guerrier, ce qui a tendance à créer des tensions dans l’armée de\n« L’émeraude sanglante ».","source_heading":"Ral’var IV"},"sections":[{"id":"chasseurs-profil-source","title":"Profil — dossier Chasseurs","level":2,"blocks":[{"type":"table","rows":[["Nom de la Réalité","GONG Min-Ju"],["Nom de la Vérité","Ral’var IV"],["Âge","« 25 ans « - ?? ans"],["Affiliations","chasseurs alien"],["Nationalité d’origine","Nord-coréenne"],["Nature réelle","Tallasse"],["Repère","Chasseur de l’Emeraude Sanglante"]]}]},{"id":"chasseurs-informations-mj","title":"Informations MJ — dossier Chasseurs","level":2,"audience":"mj","blocks":[{"type":"p","text":"« L’émeraude sanglante » compte de nombreux combattants d’élite qui n’ont rien à envier aux plus grands héros humains. Ral’var IV en est le meilleur exemple, loyal bras droit du général Saoden, ce terroriste a déjà envoyé voler deux fois de suite A-man qui tenta de l’arrêter. Son armure est un modèle custom de « Malbeol II » (frelon en coréen) dont la principale fonction est de lui conférer la résistance et la force que les talass n’ont pas afin de mettre à contribution leurs réflexes et leur agilité prodigieuse. Ral’var est plus réputé encore sur le champ de bataille que Saoden en personne et c’est pourquoi il est le plus célèbre des « Emeraldiens » chasseurs. Il a beaucoup de mal à s’intégrer dans la Réalité, ayant opté pour une apparence de jeune homme séduisant pour se donner plus de chances de sembler normal, on le confond avec des personnalités connues, subissant un harcèlement constant des groupies d’un groupe de K-pop dont un des membres est son sosie. C’est un handicapé social qui n’a aucun talent pour les interactions n’étant pas guerrières, tactiques et bien organisées. Sa cible prioritaire est Tejana (Nel’Akna), qu’il considère être une grande menace mais il organise depuis plusieurs années l’anéantissement du Xenoshield, qu’il ne supporte pas. Hélas pour lui, Saoden apprécie utiliser les humains de cette organisation pour acculer des cibles sans mobiliser le moindre guerrier, ce qui a tendance à créer des tensions dans l’armée de « L’émeraude sanglante »."}]},{"id":"profil-statistique","title":"Profil statistique","level":2,"audience":"mj","blocks":[]}]}] as Array<Record<string, any>>;
export default PAYLOAD;
